      // 输出最终统计\n            def jarCount = outputDir.listFiles()?.count { it.name.endsWith(".jar") } ?: 0\n            println "\\n" + "=" * 50\n            println "Extraction Result: ${jarCount} JAR(s) exported to ${outputDir.absolutePath}"\n            println "=" * 50\n            if (jarCount == 0) println "WARNING: No JAR files extracted (check dependencies/configurations)"\n        }\n    }\n    \n    // 一键执行任务（先clean再提取）\n    task downloadJars {\n        dependsOn clean, extractAarJars\n        extractAarJars.mustRunAfter clean\n        doLast { println " All JAR files extracted successfully!" }\n    }\n    \n    // 任务描述\n    extractAarJars.description = "Extracts JAR files from dependencies (raw JARs and AAR-contained JARs)"\n    downloadJars.description = "Cleans and extracts all dependency JAR files"\n}\n')])]),n._v(" "),s("div",{staticClass:"line-numbers-wrapper"},[s("span",{staticClass:"line-number"},[n._v("1")]),s("br"),s("span",{staticClass:"line-number"},[n._v("2")]),s("br"),s("span",{staticClass:"line-number"},[n._v("3")]),s("br"),s("span",{staticClass:"line-number"},[n._v("4")]),s("br"),s("span",{staticClass:"line-number"},[n._v("5")]),s("br"),s("span",{staticClass:"line-number"},[n._v("6")]),s("br"),s("span",{staticClass:"line-number"},[n._v("7")]),s("br"),s("span",{staticClass:"line-number"},[n._v("8")]),s("br"),s("span",{staticClass:"line-number"},[n._v("9")]),s("br"),s("span",{staticClass:"line-number"},[n._v("10")]),s("br"),s("span",{staticClass:"line-number"},[n._v("11")]),s("br"),s("span",{staticClass:"line-number"},[n._v("12")]),s("br"),s("span",{staticClass:"line-number"},[n._v("13")]),s("br"),s("span",{staticClass:"line-number"},[n._v("14")]),s("br"),s("span",{staticClass:"line-number"},[n._v("15")]),s("br"),s("span",{staticClass:"line-number"},[n._v("16")]),s("br"),s("span",{staticClass:"line-number"},[n._v("17")]),s("br"),s("span",{staticClass:"line-number"},[n._v("18")]),s("br"),s("span",{staticClass:"line-number"},[n._v("19")]),s("br